import{_ as a,o,c as i,a2 as t}from"./chunks/framework.DCVnL8g5.js";const p=JSON.parse('{"title":"Introducción al ecosistema Hugging Face","description":"","frontmatter":{},"headers":[],"relativePath":"ia/huggingface/01-introduccion-al-ecosistema.md","filePath":"ia/huggingface/01-introduccion-al-ecosistema.md","lastUpdated":1789040978000,"isDraft":false}'),n={name:"ia/huggingface/01-introduccion-al-ecosistema.md"};function r(s,e,c,l,d,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="introduccion-al-ecosistema-hugging-face" tabindex="-1">Introducción al ecosistema Hugging Face <a class="header-anchor" href="#introduccion-al-ecosistema-hugging-face" aria-label="Permalink to &quot;Introducción al ecosistema Hugging Face&quot;">​</a></h1><p>Hugging Face es sobre todo un <strong>Hub</strong> (git + artefactos de ML) y un conjunto de <strong>bibliotecas</strong> para usar esos artefactos. El Hub hospeda modelos, datasets y demos (Spaces). Las librerías más habituales en este manual:</p><table tabindex="0"><thead><tr><th>Pieza</th><th>Para qué</th></tr></thead><tbody><tr><td>Hub</td><td>Descubrir, versionar y descargar pesos y datos.</td></tr><tr><td><code>transformers</code></td><td>Cargar modelos y hacer inferencia o fine-tuning.</td></tr><tr><td><code>datasets</code></td><td>Leer y transformar datasets (capítulo 3).</td></tr><tr><td><code>huggingface_hub</code></td><td>Login, upload/download programático.</td></tr></tbody></table><p>No es un único producto “el modelo”: un id tipo <code>org/nombre</code> apunta a un <strong>repositorio</strong> con config, tokenizer, pesos y una model card.</p><p>Documentación oficial: <a href="https://huggingface.co/docs/hub/index" target="_blank" rel="noreferrer">Hub</a>, <a href="https://huggingface.co/docs/transformers/en/quicktour" target="_blank" rel="noreferrer">Transformers quickstart</a>.</p><h2 id="que-vas-a-hacer-en-la-practica" tabindex="-1">Qué vas a hacer en la práctica <a class="header-anchor" href="#que-vas-a-hacer-en-la-practica" aria-label="Permalink to &quot;Qué vas a hacer en la práctica&quot;">​</a></h2><ol><li>Elegir un modelo en el Hub (tarea, licencia, tamaño, si es gated).</li><li>Autenticarte si el repo es privado o gated.</li><li>Cargarlo con <code>from_pretrained</code> o con <code>pipeline</code> (siguiente capítulo).</li><li>Cachear pesos en disco (por defecto <code>~/.cache/huggingface</code>).</li></ol><p>Login con el CLI actual:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>Crea un <a href="https://huggingface.co/docs/hub/security-tokens" target="_blank" rel="noreferrer">access token</a> en la web. No lo subas al git; en CI usa un secret.</p><h2 id="relacion-con-el-resto-del-manual" tabindex="-1">Relación con el resto del manual <a class="header-anchor" href="#relacion-con-el-resto-del-manual" aria-label="Permalink to &quot;Relación con el resto del manual&quot;">​</a></h2><ul><li><strong>Transformers / pipelines / tokenizers:</strong> cómo pasa el texto a ids y cómo se llama al modelo. Siguiente capítulo.</li><li><strong>Datasets:</strong> <code>load_dataset</code>, streaming, map.</li><li><strong>Hub y modelos:</strong> cards, gated, <code>revision</code>.</li><li><strong>Fine-tuning y evaluación:</strong> Trainer, métricas.</li><li><strong>Despliegue:</strong> Inference Providers, Inference Endpoints, o un servidor propio (vLLM en este mismo área). Spaces es demo, no API de producción.</li></ul><p>Si tu objetivo es <strong>servir</strong> un LLM con alta concurrencia, Hugging Face te da los pesos; el servidor puede ser vLLM, no <code>pipeline</code> en un Flask.</p><h2 id="cache-y-descargas" tabindex="-1">Cache y descargas <a class="header-anchor" href="#cache-y-descargas" aria-label="Permalink to &quot;Cache y descargas&quot;">​</a></h2><p><code>from_pretrained(&quot;Qwen/Qwen2.5-0.5B-Instruct&quot;)</code> descarga (o reutiliza) el snapshot al cache local. Controla la revisión (<code>revision=&quot;...&quot;</code>) cuando necesites reproducibilidad. No asumas que <code>main</code> del Hub es inmutable.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Tratar el Hub como “un CDN anónimo” y pegar pesos en el repo git. El git del proyecto apunta al id; los binarios viven en el Hub/cache.</li><li>Usar un modelo gated sin token: el error parece de red y no de auth.</li><li>Ignorar la model card (licencia, datos de entrenamiento, limitaciones).</li><li>Cargar un LLM enorme con <code>pipeline</code> en CPU “para probar” y quedarse sin RAM. Empieza por un modelo pequeño.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Fija el <strong>id completo</strong> del modelo en el código o en config, no “el de sentimiento por defecto”.</li><li>Revisa tarea (<code>text-generation</code>, <code>token-classification</code>, …) antes de copiar un snippet.</li><li>En servidores, monta el cache en volumen (igual que en el capítulo de despliegue de vLLM).</li><li><code>hf auth login</code> es el comando actual; no documentes <code>huggingface-cli login</code> como receta nueva.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Crea cuenta y un token de lectura. Ejecuta <code>hf auth login</code>.</li><li>Abre en el Hub un modelo pequeño de generación y anota licencia y tamaño.</li><li>En el siguiente capítulo cárgalo con <code>pipeline</code> usando ese id.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./02-transformers-pipelines-y-tokenizers">Transformers, pipelines y tokenizers</a>.</p>',23)])])}const h=a(n,[["render",r]]);export{p as __pageData,h as default};
